Bash(powershell -Command '
$json = Get-Content "C:\\Users\\josem\\Desktop\\HAT3X\\CLAUDE\\HAT3X\\workflow_ekis.json" -Raw | ConvertFrom-Json

Write-Host "=== TODAS LAS CONEXIONES DEL WORKFLOW ==="
foreach \($conn in $json.connections\) {
    $fromNode = \($json.nodes | Where-Object {$_.id -eq $conn.from.nodeId}\)
    $toNode = \($json.nodes | Where-Object {$_.id -eq $conn.to.nodeId}\)
    $fromName = if\($fromNode\) { $fromNode.name } else { $conn.from.nodeId }
    $toName = if\($toNode\) { $toNode.name } else { $conn.to.nodeId }
    Write-Host "  $\($fromName\) --> $\($toName\)"
}
')

Bash(powershell -Command "
\\$json = Get-Content 'C:/tmp/wf_original.json' -Raw | ConvertFrom-Json
\\$nodes = \\$json.nodes | Where-Object { \\$_.type -like '*googleSheets*' }
\\$result = \\$nodes | ForEach-Object {
    [PSCustomObject]@{
        name = \\$_.name
        operation = \\$_.parameters.operation
        documentId = \\$_.parameters.documentId
        spreadsheet = \\$_.parameters.spreadsheetId
        sheet = \\$_.parameters.sheetName
        columns = if \(\\$_.parameters.columns\) { \\$_.parameters.columns.value } else { 'NULL' }
    }
}
\\$result | ConvertTo-Json -Depth 10
")

